register_rest_route(
    HOSTINGER_REACH_PLUGIN_REST_API_BASE,
    'contact',
    array(
        'methods'             => 'POST',
        'callback'            => array( $this->handler, 'post_contact_handler' ),
        'permission_callback' => '__return_true',
        'args'                => array(
            'id'       => array(
                'required' => true,
                'type'     => 'string',
            ),
            'group'    => array(
                'required'          => false,
                'default'           => HOSTINGER_REACH_DEFAULT_CONTACT_LIST,
                'type'              => 'string',
                'validate_callback' => array( $this, 'is_valid_contact_list' ),
            ),
            'tags'     => array(
                'required' => false,
                'default'  => HOSTINGER_REACH_DEFAULT_CONTACT_LIST,
                'type'     => 'string',
            ),
            'email'    => array(
                'required'          => true,
                'type'              => 'string',
                'validate_callback' => function ( $param ) {
                    return filter_var( $param, FILTER_VALIDATE_EMAIL );
                },
            ),
            'name'     => array(
                'required' => false,
                'default'  => '',
                'type'     => 'string',
            ),
            'surname'  => array(
                'required' => false,
                'default'  => '',
                'type'     => 'string',
            ),
            'metadata' => array(
                'required'   => false,
                'type'       => 'object',
                'properties' => array(
                    'plugin' => array(
                        'type' => 'string',
                    ),
                ),
            ),
        ),
    )
);

register_rest_route(
    HOSTINGER_REACH_PLUGIN_REST_API_BASE,
    'tags',
    array(
        array(
            'methods'             => 'GET',
            'callback'            => array( $this->handler, 'get_tags_handler' ),
            'permission_callback' => array( $this, 'permission_check' ),
        ),
        array(
            'methods'             => 'POST',
            'callback'            => array( $this->handler, 'post_tags_handler' ),
            'permission_callback' => array( $this, 'permission_check' ),
            'args'                => array(
                'names' => array(
                    'type'     => 'array',
                    'required' => true,
                    'default'  => array( HOSTINGER_REACH_DEFAULT_CONTACT_LIST ),
                    'items'    => array(
                        'type' => 'string',
                    ),
                ),
            ),
        ),

    )
);
